import random
import string
from typing import List

# Data type: alphanumeric+underscore string, max length 32, non-empty
# Fuzzer stub uses FUZZ_PARAM_STR to build an environment variable name by
# filtering to [A-Za-z0-9_] and truncating to 32 chars. If empty after filtering,
# the stub falls back to "FUZZ_ENV_TEST". To exercise the target, we want to
# provide valid names directly so the stub uses our data.
#
# Strategy:
# - Generate diverse environment variable-like names within 1..32 chars.
# - Include edge cases: length 1, length 32, uppercase-only, lowercase-only,
#   mixed case, starts with underscore, starts with digit (allowed by stub),
#   repeated underscores, alternating patterns, random.
# - Return as bytes (UTF-8 ASCII) since FUZZ framework will consume a byte buffer
#   for FUZZ_PARAM_STR.

ALNUM_US = string.ascii_letters + string.digits + "_"


def _make_name(rng: random.Random) -> str:
    # Choose one of several patterns to diversify behavior
    choice = rng.randrange(10)
    max_len = 32

    if choice == 0:
        # Minimal length
        return rng.choice(string.ascii_letters + "_")
    elif choice == 1:
        # Max length all uppercase
        return "".join(rng.choices(string.ascii_uppercase + "_", k=max_len))
    elif choice == 2:
        # Max length all lowercase
        return "".join(rng.choices(string.ascii_lowercase + "_", k=max_len))
    elif choice == 3:
        # Starts with underscore, mixed rest
        length = rng.randint(2, max_len)
        return "_" + "".join(rng.choices(ALNUM_US, k=length - 1))
    elif choice == 4:
        # Starts with digit (allowed by stub), followed by letters
        length = rng.randint(2, max_len)
        return rng.choice(string.digits) + "".join(
            rng.choices(string.ascii_letters + string.digits + "_", k=length - 1)
        )
    elif choice == 5:
        # Alternating letters and digits
        length = rng.randint(4, max_len)
        s = []
        for i in range(length):
            if i % 2 == 0:
                s.append(rng.choice(string.ascii_letters))
            else:
                s.append(rng.choice(string.digits))
        return "".join(s)
    elif choice == 6:
        # Many underscores
        length = rng.randint(3, max_len)
        underscores = "_" * rng.randint(1, length // 2)
        rest_len = length - len(underscores)
        rest = "".join(rng.choices(string.ascii_letters + string.digits, k=rest_len))
        # Shuffle to distribute underscores
        chars = list(underscores + rest)
        rng.shuffle(chars)
        return "".join(chars)
    elif choice == 7:
        # CamelCase-like
        chunks = [
            rng.choice(string.ascii_uppercase) + "".join(rng.choices(string.ascii_lowercase, k=rng.randint(1, 6)))
            for _ in range(rng.randint(1, 4))
        ]
        name = "_".join(chunks)
        return name[:max_len]
    elif choice == 8:
        # Repeated token
        token = rng.choice(["ENV", "VAR", "TEST", "CFG"]) + rng.choice(["_", ""]) \
                + rng.choice(["1", "2", "A", "B"]) 
        reps = max(1, min(8, 32 // max(1, len(token))))
        s = (token * reps)[:max_len]
        # Ensure valid chars only (they are), and non-empty
        return s if s else "A"
    else:
        # Fully random length and charset within constraints
        length = rng.randint(1, max_len)
        return "".join(rng.choices(ALNUM_US, k=length))


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    name = _make_name(rng)
    # Ensure not empty and within 32 ASCII alnum+underscore characters
    if not name:
        name = "A"
    if len(name) > 32:
        name = name[:32]
    # All characters are ASCII-safe; encode to bytes
    return name.encode("ascii", errors="strict")
